 const string Root="Assets/Realmwalker";
 static readonly Dictionary<string,Material> mats=new Dictionary<string,Material>();
 static int serial; static bool refining;
 static Vector3 V(float x,float y,float z)=>new Vector3(x,y,z);
 static Transform Group(string name,Transform parent){var t=new GameObject(name).transform;t.SetParent(parent,false);return t;}
 static Material Mat(string name,Color color,float metal=0,float smooth=.3f){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name,enableInstancing=true};m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",smooth);m.SetFloat("_Cull",0);string path=Root+"/Materials/"+name+".mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing!=null){EditorUtility.CopySerialized(m,existing);Object.DestroyImmediate(m);m=existing;}else AssetDatabase.CreateAsset(m,path);mats[name]=m;return m;}
 static Transform MeshObject(string name,Transform parent,Vector3[] v,int[] tris,string material){var mesh=new Mesh{name=name};mesh.vertices=v;mesh.triangles=tris;mesh.RecalculateNormals();mesh.RecalculateBounds();var uv=v.Select(p=>new Vector2(p.x+p.z,p.y)).ToArray();mesh.uv=uv;mesh.RecalculateTangents();string path=Root+"/Meshes/"+(serial++).ToString("D3")+"_"+name+".asset";mesh.name=Path.GetFileNameWithoutExtension(path);var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null){existing.Clear();existing.vertices=mesh.vertices;existing.triangles=mesh.triangles;existing.uv=mesh.uv;existing.normals=mesh.normals;existing.tangents=mesh.tangents;existing.bounds=mesh.bounds;EditorUtility.SetDirty(existing);Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,path);var t=Group(name,parent);t.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=mats[material];return t;}
 static Transform Loft(string name,Transform parent,Vector3[] centers,Vector2[] radii,string mat,int sides=12){var vs=new List<Vector3>();var ts=new List<int>();for(int j=0;j<centers.Length;j++)for(int i=0;i<sides;i++){float a=i*Mathf.PI*2/sides;vs.Add(centers[j]+V(Mathf.Cos(a)*radii[j].x,0,Mathf.Sin(a)*radii[j].y));}for(int j=0;j<centers.Length-1;j++)for(int i=0;i<sides;i++){int a=j*sides+i,b=j*sides+(i+1)%sides;ts.AddRange(new[]{a,a+sides,b,b,a+sides,b+sides});}int lo=vs.Count;vs.Add(centers[0]);int hi=vs.Count;vs.Add(centers.Last());for(int i=0;i<sides;i++){int next=(i+1)%sides;ts.AddRange(new[]{lo,i,next,hi,(centers.Length-1)*sides+next,(centers.Length-1)*sides+i});}return MeshObject(name,parent,vs.ToArray(),ts.ToArray(),mat);}
 static Transform Form(string name,Transform parent,Vector3 center,Vector3 size,string mat,int rings=7,int sides=12){var c=new Vector3[rings+1];var rad=new Vector2[rings+1];for(int i=0;i<=rings;i++){float a=-Mathf.PI/2+i*Mathf.PI/rings;c[i]=Vector3.up*Mathf.Sin(a)*size.y;float k=Mathf.Max(.015f,Mathf.Cos(a));rad[i]=new Vector2(size.x*k,size.z*k);}var result=Loft(name,parent,c,rad,mat,sides);result.localPosition=center;return result;}
 static Transform Tube(string name,Transform parent,Vector3 a,Vector3 b,float radius,string mat,float taper=1){float len=Vector3.Distance(a,b);var t=Loft(name,parent,new[]{Vector3.zero,V(0,len*.13f,0),V(0,len*.87f,0),V(0,len,0)},new[]{new Vector2(radius*.85f,radius*.8f),new Vector2(radius,radius*.86f),new Vector2(radius*taper,radius*taper*.85f),new Vector2(radius*taper*.85f,radius*taper*.72f)},mat);t.localPosition=a;t.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);return t;}
 static void Ribbon(string name,Transform parent,Vector3[] centers,float[] widths,string mat){var v=new List<Vector3>();var tri=new List<int>();for(int i=0;i<centers.Length;i++){v.Add(centers[i]+Vector3.left*widths[i]);v.Add(centers[i]+Vector3.right*widths[i]);}for(int i=0;i<centers.Length-1;i++){int a=i*2;tri.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}MeshObject(name,parent,v.ToArray(),tri.ToArray(),mat);}
 static void BuildModel(Transform model){var body=Group("Body_SeparateRigidParts",model);var clothing=Group("Clothing_LeatherAndSteel",model);var accessories=Group("Accessories",model);var head=Group("Head_FaceAndHair",body);
