 Loft("RuggedBootShaft",leg,new[]{V(s*.135f,.13f,0),V(s*.135f,.21f,0),V(s*.135f,.43f,0),V(s*.135f,.46f,0)},new[]{new Vector2(.086f,.087f),new Vector2(.08f,.073f),new Vector2(.092f,.08f),new Vector2(.098f,.085f)},"BootLeather");
 Form("BootFoot",leg,V(s*.135f,.09f,.063f),V(.094f,.085f,.171f),"BootLeather");Form("BootSole",leg,V(s*.135f,.025f,.064f),V(.096f,.025f,.174f),"DarkTrim");Form("KneeGuard",leg,V(s*.13f,.57f,.07f),V(.083f,.10f,.033f),"Steel");
 for(int j=0;j<2;j++){Form("BootStrap",leg,V(s*.135f,.24f+j*.12f,.075f),V(.08f,.018f,.015f),"LeatherLight");Form("BootBuckle",leg,V(s*.17f,.24f+j*.12f,.09f),V(.018f,.022f,.008f),"Brass");}
 var arm=Group(s<0?"LeftArm_APose":"RightArm_APose",body);Vector3 shoulder=V(s*.255f,1.44f,0),elbow=V(s*.38f,1.19f,0),wrist=V(s*.47f,.98f,.015f);Tube("SleeveUpper",arm,shoulder,elbow,.092f,"Leather",.85f);Tube("SleeveForearm",arm,elbow,wrist,.073f,"Leather",.8f);Tube("Bracer",arm,Vector3.Lerp(elbow,wrist,.28f),wrist,.079f,"Steel",.77f);Form("GlovedHand",arm,V(s*.49f,.925f,.022f),V(.064f,.088f,.047f),"BootLeather");Form("GloveThumb",arm,V(s*.445f,.933f,.052f),V(.025f,.052f,.025f),"LeatherLight");
 for(int finger=0;finger<3;finger++)Tube("GloveSeam",arm,V(s*(.46f+finger*.022f),.92f,.063f),V(s*(.46f+finger*.022f),.87f,.054f),.003f,"LeatherLight");
 for(int layer=0;layer<3;layer++){var pauldron=Form("LayeredPauldron",clothing,V(s*(.254f+layer*.038f),1.475f-layer*.036f,0),V(.125f-layer*.018f,.055f,.125f-layer*.012f),layer==0?"Steel":"DarkTrim");pauldron.localRotation=Quaternion.Euler(0,0,-s*13);}
 Form("PauldronRivet",accessories,V(s*.29f,1.5f,.115f),V(.012f,.012f,.008f),"Brass");
 Form("BeltPouch",accessories,V(s*.207f,1.025f,.06f),V(.068f,.093f,.058f),"BootLeather");Form("PouchFlap",accessories,V(s*.207f,1.069f,.103f),V(.069f,.045f,.022f),"LeatherLight");Form("PouchStud",accessories,V(s*.207f,1.04f,.126f),V(.008f,.008f,.005f),"Brass");
 Ribbon("SplitTunicPanel",clothing,new[]{V(s*.105f,1.04f,.122f),V(s*.12f,.91f,.136f),V(s*.13f,.825f,.125f)},new[]{.085f,.09f,.073f},"LeatherLight");
 Form("Ear",head,V(s*.124f,1.735f,0),V(.026f,.044f,.025f),"Skin");Form("EarInset",head,V(s*.134f,1.736f,.016f),V(.013f,.027f,.01f),"SkinShadow");
 Form("EyeSocket",head,V(s*.051f,1.767f,.094f),V(.032f,.021f,.012f),"SkinShadow");Form("EyeWhite",head,V(s*.051f,1.768f,.102f),V(.024f,.010f,.006f),"Ivory");Form("Iris",head,V(s*.049f,1.768f,.108f),V(.010f,.010f,.004f),"Iris");Form("Pupil",head,V(s*.049f,1.769f,.112f),V(.0045f,.007f,.002f),"DarkTrim");Form("EyeGlint",head,V(s*.047f,1.773f,.114f),V(.002f,.002f,.001f),"Ivory");
 var brow=Form("ThickEyebrow",head,V(s*.053f,1.799f,.104f),V(.039f,.012f,.014f),"HairDark",5,10);brow.Rotate(0,0,s*8);
 Tube("BeardJawEdge",head,V(s*.097f,1.715f,.055f),V(s*.057f,1.635f,.075f),.014f,"HairDark",1.05f);
 }
 Form("Neck",body,V(0,1.56f,0),V(.066f,.10f,.065f),"Skin");Form("SculptedHead",head,V(0,1.748f,0),V(.12f,.151f,.107f),"Skin",10,16); // face is built forward of the head surface
 Form("NoseBridge",head,V(0,1.735f,.111f),V(.021f,.044f,.023f),"Skin");Form("NoseTip",head,V(0,1.710f,.136f),V(.021f,.015f,.017f),"Skin");
 Form("ShortBeardChin",head,V(0,1.633f,.041f),V(.071f,.032f,.064f),"HairDark");Form("LowerLip",head,V(0,1.674f,.104f),V(.035f,.007f,.008f),"SkinShadow");for(int s=-1;s<=1;s+=2){var m=Form("Moustache",head,V(s*.023f,1.691f,.106f),V(.031f,.011f,.015f),"HairDark");m.Rotate(0,0,-s*12);}
 Form("HairBack",head,V(0,1.79f,-.049f),V(.121f,.105f,.078f),"HairDark",8,14);
 for(int i=0;i<8;i++){float x=-.105f+i*.028f;Loft("SweptHairLock",head,new[]{V(x,1.81f,.032f),V(x-.006f,1.862f,.068f),V(x+.018f,1.903f,.036f),V(x+.061f,1.916f+.009f*Mathf.Sin(i*.5f),-.037f)},new[]{new Vector2(.027f,.037f),new Vector2(.03f,.043f),new Vector2(.029f,.043f),new Vector2(.003f,.005f)},i%3==0?"HairWarm":"Hair",8);}
 Loft("WaistBelt",accessories,new[]{V(0,1.05f,0),V(0,1.105f,0)},new[]{new Vector2(.175f,.123f),new Vector2(.175f,.123f)},"BootLeather",16);Form("Buckle",accessories,V(0,1.078f,.131f),V(.042f,.035f,.015f),"Brass");Form("BuckleInset",accessories,V(0,1.078f,.145f),V(.026f,.021f,.006f),"DarkTrim");
 Ribbon("DiagonalHarness",accessories,new[]{V(-.18f,1.46f,.103f),V(-.08f,1.3f,.158f),V(.12f,1.09f,.126f)},new[]{.028f,.027f,.027f},"BootLeather");
 for(int i=0;i<3;i++)Form("HarnessStud",accessories,V(-.13f+i*.062f,1.385f-i*.075f,.163f),V(.006f,.006f,.004f),"Brass");
 Loft("CharcoalScarfWrap",clothing,new[]{V(0,1.45f,.01f),V(0,1.49f,.018f),V(0,1.57f,0),V(0,1.6f,0)},new[]{new Vector2(.14f,.105f),new Vector2(.175f,.127f),new Vector2(.135f,.10f),new Vector2(.10f,.085f)},"Scarf",16);
 
 Ribbon("ScarfTail",clothing,new[]{V(.10f,1.5f,.14f),V(.16f,1.37f,.16f),V(.125f,1.22f,.16f)},new[]{.045f,.045f,.025f},"Scarf");
 var cv=new List<Vector3>();var ct=new List<int>();for(int y=0;y<6;y++)for(int x=0;x<9;x++){float u=x/8f*2-1,t=y/5f;cv.Add(V(u*Mathf.Lerp(.16f,.25f,t),Mathf.Lerp(1.5f,.91f,t)+(y==5?.018f*Mathf.Cos(x*2):0),-.12f-.09f*t-.022f*Mathf.Cos(u*Mathf.PI*4)*t));}for(int y=0;y<5;y++)for(int x=0;x<8;x++){int a=y*9+x;ct.AddRange(new[]{a,a+1,a+9,a+1,a+10,a+9});}MeshObject("ShortDrapedCape",clothing,cv.ToArray(),ct.ToArray(),"Cape");
 for(int s=-1;s<=1;s+=2)Tube("CapeEdgeStitch",clothing,V(s*.16f,1.5f,-.12f),V(s*.25f,.92f,-.22f),.005f,"LeatherLight");
 Form("ScarfClasp",accessories,V(-.12f,1.49f,.124f),V(.031f,.031f,.013f),"Brass");Form("QuietAmberInset",accessories,V(-.12f,1.49f,.137f),V(.014f,.021f,.007f),"Amber");
