 [MenuItem("Tools/Lost Worlds/R1A/Create Realmwalker Preview")]
 public static void Build(){if(!refining&&File.Exists(Root+"/Realmwalker_Player.prefab"))throw new Exception("Prefab already exists; no assets overwritten.");foreach(var d in new[]{"Meshes","Materials","Preview","Validation"})Directory.CreateDirectory(Root+"/"+d);AssetDatabase.Refresh();serial=0;mats.Clear();
 Mat("Leather",new Color(.27f,.12f,.052f));Mat("LeatherLight",new Color(.43f,.235f,.105f));Mat("BootLeather",new Color(.115f,.061f,.035f));Mat("Trousers",new Color(.17f,.18f,.15f));Mat("Steel",new Color(.16f,.19f,.21f),.65f,.37f);Mat("DarkTrim",new Color(.055f,.065f,.068f),.15f);Mat("Scarf",new Color(.105f,.115f,.12f));Mat("ScarfEdge",new Color(.18f,.19f,.19f));Mat("Cape",new Color(.09f,.115f,.105f));Mat("Brass",new Color(.64f,.40f,.13f),.65f,.42f);Mat("Skin",new Color(.65f,.40f,.25f));Mat("SkinShadow",new Color(.37f,.18f,.115f));Mat("Hair",new Color(.16f,.075f,.029f));Mat("HairDark",new Color(.075f,.035f,.02f));Mat("HairWarm",new Color(.24f,.12f,.043f));Mat("Ivory",new Color(.86f,.80f,.66f));Mat("Iris",new Color(.18f,.29f,.22f));var amber=Mat("Amber",new Color(.85f,.51f,.13f),.2f);amber.EnableKeyword("_EMISSION");amber.SetColor("_EmissionColor",new Color(.16f,.07f,.005f));
 var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var model=Group("Realmwalker_Player",null);BuildModel(model);PrefabUtility.SaveAsPrefabAsset(model.gameObject,Root+"/Realmwalker_Player.prefab");Object.DestroyImmediate(model.gameObject);var instance=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Realmwalker_Player.prefab"));
 RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.38f,.42f,.48f);RenderSettings.fog=false;var key=new GameObject("Preview_Key").AddComponent<Light>();key.type=LightType.Directional;key.intensity=2.1f;key.color=new Color(1,.86f,.72f);key.transform.rotation=Quaternion.Euler(35,-145,0);key.shadows=LightShadows.Soft;var fill=new GameObject("Preview_Fill").AddComponent<Light>();fill.type=LightType.Directional;fill.intensity=.8f;fill.color=new Color(.64f,.77f,1);fill.transform.rotation=Quaternion.Euler(20,40,0);var cam=new GameObject("PreviewCamera_Only").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.07f,.085f,.10f);cam.orthographic=true;cam.orthographicSize=1.12f;cam.transform.position=V(2.5f,1.7f,5);cam.transform.LookAt(V(0,.98f,0));cam.nearClipPlane=.03f;cam.farClipPlane=30;EditorSceneManager.SaveScene(scene,Root+"/Preview/Realmwalker_Preview.unity");AssetDatabase.SaveAssets();var used=new HashSet<string>(AssetDatabase.GetDependencies(Root+"/Realmwalker_Player.prefab",true));foreach(var folder in new[]{"Meshes","Materials"})foreach(var guid in AssetDatabase.FindAssets("",new[]{Root+"/"+folder})){var path=AssetDatabase.GUIDToAssetPath(guid);if(!AssetDatabase.IsValidFolder(path)&&!used.Contains(path))AssetDatabase.DeleteAsset(path);}EditorSceneManager.OpenScene(Root+"/Preview/Realmwalker_Preview.unity");instance=GameObject.Find("Realmwalker_Player");cam=GameObject.Find("PreviewCamera_Only").GetComponent<Camera>();Validate(instance);Capture(cam);AssetDatabase.Refresh();}
 static void Validate(GameObject go){var meshes=go.GetComponentsInChildren<MeshFilter>();int tris=0;foreach(var f in meshes){if(f.sharedMesh==null||f.GetComponent<Renderer>().sharedMaterial==null)throw new Exception("Missing mesh/material");tris+=f.sharedMesh.triangles.Length/3;}if(go.GetComponentsInChildren<MonoBehaviour>().Length!=0||go.GetComponentsInChildren<Collider>().Length!=0||go.GetComponentsInChildren<Camera>().Length!=0)throw new Exception("Unexpected gameplay component");var rs=go.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);if(Mathf.Abs(bounds.min.y)>.005f)throw new Exception("Feet not grounded");Debug.Log("REALMWALKER PASS: "+meshes.Length+" mesh parts, "+tris+" triangles; height "+bounds.size.y+"m; no scripts/colliders/cameras; valid mesh/material references.");File.WriteAllText(Root+"/Validation/Result.txt",meshes.Length+" mesh parts; "+tris+" triangles; "+bounds.size.y+"m tall. +Z forward, feet at y=0. No runtime behaviour.\nRigid separate meshes; no skeleton, skin weights, humanoid Avatar, animation or UV unwrap yet. R1B must consolidate/retopologize deforming joints and skin the model; procedural projection UVs are not paint-ready.\n");}
 static void Capture(Camera cam){var pipeline=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;var copy=Object.Instantiate(pipeline);var previous=QualitySettings.renderPipeline;var rt=new RenderTexture(900,1100,24);var tex=new Texture2D(900,1100,TextureFormat.RGB24,false);var active=RenderTexture.active;try{copy.gpuResidentDrawerMode=GPUResidentDrawerMode.Disabled;copy.useSRPBatcher=false;QualitySettings.renderPipeline=copy;var poses=new[]{V(0,1.18f,5),V(4,1.4f,4),V(5,1.18f,0),V(0,1.18f,-5)};var names=new[]{"Front","ThreeQuarter","Side","Rear"};for(int i=0;i<poses.Length;i++){cam.transform.position=poses[i];cam.transform.LookAt(V(0,.98f,0));for(int j=0;j<3;j++)RenderPipeline.SubmitRenderRequest(cam,new RenderPipeline.StandardRequest{destination=rt,isPreview=true});RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,900,1100),0,0);tex.Apply();File.WriteAllBytes(Root+"/Preview/"+names[i]+".png",tex.EncodeToPNG());}}finally{QualitySettings.renderPipeline=previous;RenderTexture.active=active;rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(tex);Object.DestroyImmediate(copy);}}
 public static void RefineBatch(){refining=true;BuildBatch();}
 public static void BuildBatch()=>EditorApplication.delayCall+=()=>{try{Build();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}};
